"""Publish only against a successful, current real-museum review."""
from pathlib import Path
import json,hashlib,shutil,markdown,ast
R=Path(__file__).resolve().parents[1]
O=R/'doc/research/possible-bodies';E=R/'doc/space/ca-life-review-2026-09-13'
RUN=R/'ada_run/ca-life-review-2026-09-13'
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def save(p,text):
 p.parent.mkdir(parents=True,exist_ok=True)
 t=p.with_name(p.name+'.life-tmp');t.write_bytes((text.strip()+'\n').encode());t.replace(p)
receipt=json.loads((RUN/'run.json').read_text())
assert receipt['exit']==0 and not receipt['failures'] and receipt['sources_unchanged']
assert all(sha(R/p)==h for p,h in receipt['source_sha256'].items()),'Stale runtime receipt'
engine=(RUN/'CA_BeyondBinary/engine.log').read_text(encoding='utf-8',errors='replace')
assert 'SCRIPT ERROR:' not in engine and 'Parse Error:' not in engine,'Resolve runtime script errors before publishing'
result=json.loads((RUN/'CA_BeyondBinary/probe_ca_life_live.json').read_text())
for name in ['entrance','controls','readout','floor','whole-hall']:
 shutil.copy2(RUN/f'CA_BeyondBinary/{name}.png',O/f'ca-life-{name}.png')
shutil.copy2(R/'tools/ca_life_model.js',O/'ca-life-model.js')
for name in ['final','technical','critical','tutorial','field_notes']:
 shutil.copy2(R/f'commons/maps/CA_BeyondBinary/{name}.md',O/f'ca-life-{name}.md')
save(E/'runtime-receipt.json',json.dumps(receipt,indent=2))
save(E/'runtime-verification.json',json.dumps(result,indent=2))
body=markdown.markdown((R/'commons/maps/CA_BeyondBinary/final.md').read_text(encoding='utf-8'),extensions=['fenced_code'])
# Reuse the neighbouring research page's typography without executing its builder.
tree=ast.parse((R/'tools/build_ca_history_review.py').read_text(encoding='utf-8'))
css=next(ast.literal_eval(n.value) for n in tree.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='css' for t in n.targets))
css+='''.experiment{display:grid;grid-template-columns:minmax(240px,520px) 1fr;gap:35px;align-items:center;margin-top:25px}#plane svg{display:block;width:100%}.lamp-row{display:flex;align-items:center;gap:20px;margin:25px 0}.lamp{width:64px;height:64px;flex-shrink:0;border-radius:50%;background:#50495b;border:2px solid #ad9779;transition:background .1s}.lamp.lit{background:#9bf4d7;box-shadow:0 0 30px #62c4a477}.lamp-row h3{margin:0}.lamp-row p{margin:0;font-size:14px}.prompt{padding:20px;background:#203e43;border-radius:8px}@media(max-width:720px){.experiment{grid-template-columns:1fr}.lamp-row{margin:12px 0}.lamp{width:45px;height:45px}}'''
html='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>A pattern visits an address · Ada Research</title><style>__CSS__</style></head><body><main><nav><a href="learning-ladder.html">← Pedagogical ladder</a><a href="ca-history-bridge.html">Previous: a history you can inhabit</a><a href="/necklace/thread?map=CA_BeyondBinary&role=primary">Primary &amp; book</a></nav><div class="eyebrow">Cellular automata / CA_BeyondBinary</div><h1>A pattern visits an address</h1><p class="lead">Five cells, a travelling figure, three lamps. What has to be connected for the museum to answer a simulation?</p><p class="status">Implemented in Godot · __CHECKS__ desktop checks passed · all six original artifacts retained. Actual museum images below. Headset review and the retained secondary encounters remain further work.</p><figure><img src="ca-life-entrance.png" alt="Actual Godot museum with a Life pattern inlaid in the floor, three cased lamp receivers and a desk beside it"><figcaption>At generation 8, address A is occupied and its lamp lights. The gold addresses stay where they are. Arrival begins held at generation zero.</figcaption></figure><section><h2>Follow the address. Then follow the figure.</h2><p>The desk and floor read one present. A gold square marks each sampled cell; the lamp receives that cell’s occupancy. The floor remains solid under empty cells as well as occupied ones. Colour, support and connection are separate decisions.</p><div class="gallery"><figure><img src="ca-life-controls.png" alt="The Life dish on a table with seven controls and a cased state display"><figcaption>STEP, RUN and REPLAY manage this experiment. GLIDER, BLINKER and MEET prepare repeatable beginnings. LINK controls its output to the lamps.</figcaption></figure><figure><img src="ca-life-floor.png" alt="A larger view of the floor array with a five-cell pattern, gold witnesses and opal lamps"><figcaption>The same pattern becomes a floor finish and a signal for objects in the room. These receivers have no influence back into Life.</figcaption></figure></div></section><section id="experiment"><h2>Try the encounter remotely</h2><p class="small">An explanatory browser model: the same 24 × 24 periodic Life rule, beginnings and three addresses. This is not a Godot physics or headset test. Generation zero waits for you.</p><p class="prompt">Press STEP four times. What returns, and what changes? Then try BLINKER: can the line turn while its middle lamp stays lit?</p><div class="controls"><button id="step">STEP</button><button id="run" aria-pressed="false">RUN</button><button id="replay">REPLAY</button><button id="glider" aria-pressed="true">GLIDER</button><button id="blinker" aria-pressed="false">BLINKER</button><button id="meet" aria-pressed="false">MEET</button><button id="link" aria-pressed="true">LINK</button></div><p id="status" role="status"></p><div class="experiment"><div id="plane"></div><div><div class="lamp-row"><div class="lamp" id="lamp-0" aria-hidden="true"></div><div><h3>A</h3><p id="lamp-state-0"></p></div></div><div class="lamp-row"><div class="lamp" id="lamp-1" aria-hidden="true"></div><div><h3>B</h3><p id="lamp-state-1"></p></div></div><div class="lamp-row"><div class="lamp" id="lamp-2" aria-hidden="true"></div><div><h3>C</h3><p id="lamp-state-2"></p></div></div><p class="small">Each lamp reads one fixed address. ONSETS counts new occupancy while connected; a seed or reconnect is not a new onset.</p></div></div><details><summary>Three comparisons to return to</summary><p>GLIDER repeats one address diagonally onward after four generations. BLINKER repeats in place after two, while A stays occupied. MEET places a four-cell block ahead of the glider; this prepared encounter is empty by generation 24.</p><p>Disconnect LINK during a lit moment. STEP continues the cells. Reconnect: the lamp answers the current state, without counting a connection as a birth.</p></details></section><section><h2>An application with its connection visible</h2><p>We have made a local rule reach into room lighting. The same approach could connect a cell to a wall panel, garment or sound: preserve the state, declare the mapping, then test what that output permits. Those further receivers still need their own implementation.</p><p>Here the useful complication is already present: a lamp can answer a pattern without recognising it. “Glider” helps the visitor anticipate a journey. The lamp knows only whether one address is occupied.</p></section><section><details><summary>Read the revised book passage</summary><div class="reading">__BODY__</div></details></section><section><details><summary>The whole hall and verification</summary><figure><img src="ca-life-whole-hall.png" alt="Actual overhead Godot view showing the front Life study and all retained works in the extended gallery"><figcaption>The front study is separated from the existing rear collection. All six works remain. The rear encounters still need individual spatial and interaction review.</figcaption></figure><figure><img src="ca-life-readout.png" alt="The cased Life readout showing preset, generation, rule, population, changed cells and connection state"></figure><p>__CHECKS__ real-engine checks cover all eighteen B3/S23 cases, periodic edges, glider translation, blinker repetition, the prepared meeting, fixed-address outputs, disconnect/reconnect, generation limit, seven actual desktop pointer controls, continuous support under occupied and empty addresses, and a walked portion of the museum margin. No runtime script errors. The existing unrelated startup UID diagnostic remains recorded.</p><p><a href="ca-life-technical.md">Technical account</a> · <a href="ca-life-critical.md">Critical text</a> · <a href="ca-life-field_notes.md">Field notes</a> · <a href="ca-life-verification.json">Verification</a></p></details></section><footer class="small"><a href="ca-life-final.md">Book source</a> · Next: CA_ExpandingSpace. What changes when the observing body becomes an input?</footer></main><script src="ca-life-model.js"></script></body></html>'''
save(O/'ca-life-addresses.html',html.replace('__CSS__',css).replace('__BODY__',body).replace('__CHECKS__',str(receipt['checks'])))
verification={'checks':receipt['checks'],'failures':receipt['failures'],'headset_verified':False,'desktop_pointer':'Synthetic mouse events through the project pointer in the actual museum','measurements':{k:result['measurements'][k] for k in ['first_lit_generation','glider_timeline','floor_colour_max_error','support_rays','margin_walk','last_step_ms']},'scope':'Primary and a portion of its museum margin; not a complete rear-gallery or headset review','source_sha256':receipt['source_sha256']}
save(O/'ca-life-verification.json',json.dumps(verification,indent=2))
manifest=[p.relative_to(R/'doc/research').as_posix() for p in O.glob('ca-life-*') if p.suffix in ['.html','.png','.js','.md','.json']]
save(E/'publish-targets.json',json.dumps(sorted(manifest),indent=2))
save(E/'publish-hashes.json',json.dumps({p:sha(R/'doc/research'/p) for p in manifest},indent=2))
print('Built Life review, real images, remote model and evidence with current source hashes.')
